exec-router:
def route(request, available):
    primary = "quality_model" if request["priority"] == "quality" else "fast_model"
    if primary in available:
        return primary
    return "local_model" if "local_model" in available else None

print(route({"priority":"quality"}, ["quality_model","local_model"]))

exec-evaluation:
def accuracy(predicted, expected):
    if not expected:
        return None
    correct = sum(p == e for p, e in zip(predicted, expected))
    return correct / len(expected)

print(accuracy(["a"], ["a","b"]))

exec-checkpoint:
def choose_epoch(logs):
    if not logs:
        return None
    best = logs[0]
    for row in logs:
        if row["validation_loss"] < best["validation_loss"]:
            best = row
    return best["epoch"]

print(choose_epoch([{"epoch":1,"validation_loss":0.9},{"epoch":2,"validation_loss":0.6}]))
